package asyncdb

import (
	"context"
	"sync"
	"sync/atomic"
	"time"
	"unsafe"
)

// ResultBuffer holds query results with reference counting
type ResultBuffer struct {
	data    []byte
	refCount int32
	freed   int32
}

func NewResultBuffer(size int) *ResultBuffer {
	buf := &ResultBuffer{
		data:     make([]byte, size),
		refCount: 1,
	}
	return buf
}

func (rb *ResultBuffer) Retain() {
	atomic.AddInt32(&rb.refCount, 1)
}

func (rb *ResultBuffer) Release() {
	if atomic.AddInt32(&rb.refCount, -1) == 0 {
		atomic.StoreInt32(&rb.freed, 1)
		rb.data = nil
	}
}

func (rb *ResultBuffer) IsFreed() bool {
	return atomic.LoadInt32(&rb.freed) == 1
}

// AsyncCallback represents a deferred result handler
type AsyncCallback struct {
	bufferPtr unsafe.Pointer // points to *ResultBuffer
	handler   func([]byte) error
	once      sync.Once
}

// ConnPool manages database connections with async operations
type ConnPool struct {
	mu        sync.RWMutex
	callbacks map[uint64]*AsyncCallback
	nextID    uint64
	recycled  chan *ResultBuffer
}

func NewConnPool() *ConnPool {
	return &ConnPool{
		callbacks: make(map[uint64]*AsyncCallback),
		recycled:  make(chan *ResultBuffer, 64),
	}
}

// SubmitQuery registers an async callback that will fire when results arrive
func (cp *ConnPool) SubmitQuery(ctx context.Context, query string, handler func([]byte) error) (uint64, error) {
	buf := NewResultBuffer(4096)

	cp.mu.Lock()
	id := cp.nextID
	cp.nextID++

	cb := &AsyncCallback{
		bufferPtr: unsafe.Pointer(buf),
		handler:   handler,
	}
	cp.callbacks[id] = cb
	cp.mu.Unlock()

	// Simulate async database operation
	go cp.executeAsync(ctx, id, buf, query)

	return id, nil
}

func (cp *ConnPool) executeAsync(ctx context.Context, id uint64, buf *ResultBuffer, query string) {
	// Simulate network latency
	select {
	case <-time.After(50 * time.Millisecond):
		// Fill buffer with "results"
		for i := range buf.data {
			buf.data[i] = byte(i % 256)
		}
	case <-ctx.Done():
		buf.Release()
		return
	}

	cp.deliverResult(id)
}

// deliverResult invokes the callback with the buffer data
func (cp *ConnPool) deliverResult(id uint64) {
	cp.mu.RLock()
	cb, exists := cp.callbacks[id]
	cp.mu.RUnlock()

	if !exists {
		return
	}

	cb.once.Do(func() {
		// Dereference the buffer pointer stored in the callback
		buf := (*ResultBuffer)(atomic.LoadPointer(&cb.bufferPtr))
		if buf != nil && !buf.IsFreed() {
			cb.handler(buf.data)
		}
	})
}

// CancelQuery cancels a pending async query and recycles the buffer
func (cp *ConnPool) CancelQuery(id uint64) {
	cp.mu.Lock()
	cb, exists := cp.callbacks[id]
	if exists {
		delete(cp.callbacks, id)
	}
	cp.mu.Unlock()

	if !exists {
		return
	}

	// Atomically nullify the pointer BEFORE releasing the buffer
	// This prevents the race: callback checks pointer -> cancel frees buffer -> callback uses freed buffer
	atomic.StorePointer(&cb.bufferPtr, nil)

	buf := (*ResultBuffer)(atomic.LoadPointer(&cb.bufferPtr))
	if buf != nil {
		buf.Release()
	}
	// Do NOT recycle - buffer ownership is unclear, let GC handle it
}

// GetRecycledBuffer returns a new buffer (no recycling to prevent use-after-free)
func (cp *ConnPool) GetRecycledBuffer() *ResultBuffer {
	return NewResultBuffer(4096)
}
